#include <avr/io.h>
#include <util/delay.h>

int main(void)
{
    DDRB |= (1 << PB5);            /* Arduino Uno 板载 LED：PB5 */

    while (1)
    {
        PORTB ^= (1 << PB5);
        _delay_ms(500);
    }
    return 0;
}

