#include <msp430.h>

int main(void)
{
    WDTCTL = WDTPW | WDTHOLD;      /* 关闭看门狗 */

    P1DIR |= BIT0;                 /* P1.0 输出（LaunchPad 板载 LED） */
    for (;;)
    {
        P1OUT ^= BIT0;
        __delay_cycles(1000000);
    }
    return 0;
}
